# Prefix for the lifecycle fixture; every command uses the real launcher framing.
fixture_root = Path(__file__).parent.parent
settings_path = fixture_root / 'provision-scenario.json'
settings = json.loads(settings_path.read_text()) if settings_path.exists() else {}
if sys.argv[1] == 'setup':
    args = sys.argv[1:]
    endpoint = args[args.index('--endpoint') + 1]
    out = Path(args[args.index('--out-dir') + 1])
    secret_input = sys.stdin.buffer.read()
    assert secret_input == b'sk-upstream-sensitive\n'
    assert 'IDORIS_OMLX_API_KEY' not in os.environ
    assert not any('sk-' in arg for arg in args)
    if settings.get('setup_code'):
        print(json.dumps({'status': 'error', 'code': settings['setup_code'], 'message': 'sk-upstream-sensitive'}))
        sys.exit(1)
    bindings = dict(args[i + 1].split('=', 1) for i, arg in enumerate(args) if arg == '--bind')
    for name in ['omlx.yaml', 'subscription.yaml']:
        (out / name).write_text('# generated by fixture\n')
    (out / 'scenario.json').write_text(json.dumps(settings.get('serve', {})))
    print(json.dumps({'status': 'ok', 'endpoint': endpoint, 'auth': 'required',
        'models': list(bindings.values()), 'bindings': bindings, 'components_dir': str(out),
        'next': {'env': {'IDORIS_COMPONENTS_DIR': str(out)}, 'needs_env': ['IDORIS_OMLX_API_KEY']}}))
    sys.exit(0)
if sys.argv[1] == 'key':
    metadata_path = fixture_root / 'fake-keys.json'
    entries = json.loads(metadata_path.read_text()) if metadata_path.exists() else []
    command = sys.argv[2]
    if command == 'issue':
        spec = json.load(sys.stdin)
        if settings.get('issue_fail'):
            sys.exit(1)
        key_id = 'vk_' + format(len(entries) + 1, '032x')
        entries.append(dict(spec, key_id=key_id, status='active', expires_at_ms=None, revoked_at_ms=None, tenant_id=None))
        entries[-1].pop('admin_scopes', None)
        metadata_path.write_text(json.dumps(entries))
        print(json.dumps({'key_id': key_id, 'secret': 'idk_' + 'a' * 64}))
    elif command == 'list':
        print(json.dumps({'keys': entries}))
    elif command == 'revoke':
        if settings.get('revoke_fail'):
            sys.exit(1)
        entry = next(entry for entry in entries if entry['key_id'] == sys.argv[3])
        was_revoked = entry['status'] == 'revoked'
        entry['status'] = 'revoked'
        metadata_path.write_text(json.dumps(entries))
        reply = {'key_id': sys.argv[3], 'revoked': not was_revoked}
        if was_revoked:
            reply['already_revoked'] = True
        print(json.dumps(reply))
    sys.exit(0)
